import unittest

from src.inventory import page, total_quantity


class TotalQuantityTest(unittest.TestCase):
    def test_sums_quantities(self):
        self.assertEqual(total_quantity([{"qty": 2}, {"qty": 3}]), 5)


class PageTest(unittest.TestCase):
    def test_first_page_has_items(self):
        self.assertTrue(len(page(list(range(10)), 0, 3)) >= 3)


if __name__ == "__main__":
    unittest.main()

